label{display:block;font-size:13px;margin:0 0 16px}input,textarea,select{display:block;width:100%;border:1px solid var(--outline);border-radius:12px;padding:12px;margin-top:8px;background:var(--surface)}textarea{min-height:180px;resize:vertical}input:focus,textarea:focus,select:focus,button:focus-visible{outline:2px solid var(--primary)}p{white-space:pre-wrap;line-height:1.5}

/* A fixed viewport avoids collapsed percentage heights in Android WebView. */
body{position:fixed;inset:0;height:auto;overflow:hidden}footer{flex-shrink:0}

